from kern import *

def bauen():
    einheit('terme.umformen_teil2')
    LP = 'M7 1 (Terme)'
    # ---------------- ausklammern ----------------
    lz = 'ausklammern'
    L(lz, 'test', 'begruenden', None, 3, LP,
      'Vier Schüler haben ausgeklammert: (1) 9y² − 6y = 3y(3y − 6); (2) 8a² − 12a = 4a(2a − 3); (3) 7b − 14b² = 7b(1 − 2b); (4) 15x + 10 = 5(3x + 2). Genau eine Umformung ist falsch. Welche Nummer ist es, und wie muss die Klammer dort richtig lauten?',
      'Falsch ist Nummer □; richtig: 9y² − 6y = 3y(□y − □)', [1, 3, 2], ['1', '9 : 3', '6 : 3'],
      [(1, 4, '4', 'Nummer 4 für falsch gehalten, obwohl 5 · 3x = 15x und 5 · 2 = 10 stimmen'),
       (1, 2, '2', 'Nummer 2 für falsch gehalten, obwohl 4a · 2a = 8a² und 4a · 3 = 12a stimmen'),
       (3, 6, '6', 'die 6 aus dem Term in die Klammer übernommen, ohne durch 3y zu teilen'),
       (2, 9, '9', 'die 9 aus dem Term in die Klammer übernommen, ohne durch 3y zu teilen')],
      'Probe durch Ausmultiplizieren: (2) 4a · 2a = 8a², 4a · 3 = 12a stimmt. (3) 7b · 1 = 7b, 7b · 2b = 14b², stimmt. (4) 5 · 3x = 15x, 5 · 2 = 10, stimmt. (1) 3y · 3y = 9y², aber 3y · 6 = 18y und nicht 6y. Richtig ist 6y : 3y = 2, also 9y² − 6y = 3y(3y − 2).',
      'Eine Probe durch Ausmultiplizieren trennt die richtige von der falschen Umformung, danach wird berichtigt; die Übungen prüfen nur eine Umformung.')
    L(lz, 'korrektur', 'transfer', None, 2, LP,
      'Mia klammert aus −6x² − 9x den Faktor −3x aus, Ben klammert den Faktor 3x aus. Beide schreiben die Klammer als □x + □. Wie lauten die beiden Klammern?',
      'Mia: −3x(□x + □); Ben: 3x(□x + □)', [2, 3, -2, -3], ['−6 : (−3)', '−9 : (−3)', '−6 : 3', '−9 : 3'],
      [(1, -2, '−6 : 3', 'bei −3x das Vorzeichen des Faktors nicht mitgeteilt, also durch +3 geteilt'),
       (2, -3, '−9 : 3', 'bei −3x das Vorzeichen des Faktors nicht mitgeteilt, also durch +3 geteilt'),
       (3, 2, '−6 : (−3)', 'bei 3x das Vorzeichen der Glieder vergessen'),
       (4, 3, '−9 : (−3)', 'bei 3x das Vorzeichen der Glieder vergessen')],
      'Mia: −6x² : (−3x) = 2x und −9x : (−3x) = 3, also −6x² − 9x = −3x(2x + 3). Ben: −6x² : 3x = −2x und −9x : 3x = −3, also 3x(−2x − 3). Probe: 3x · (−2x − 3) = −6x² − 9x. Beim Ausklammern eines negativen Faktors wechseln die Vorzeichen in der Klammer.',
      'Das Vorzeichen des ausgeklammerten Faktors bestimmt die Vorzeichen in der Klammer; die Übungen klammern nur positive Faktoren aus.')
    L(lz, 'korrektur', 'fehler', 'fehler_detektiv', 2, LP,
      'Ben soll aus 18x² − 12x den größten gemeinsamen Faktor ausklammern. Zeile 1: Der größte gemeinsame Teiler von 18 und 12 ist 3, und x steckt in beiden Gliedern, also klammert Ben 3x aus. Zeile 2: 18x² : 3x = 6x und 12x : 3x = 4. Zeile 3: Also ist 18x² − 12x = 3x(6x − 4). In welcher Zeile steckt der erste Fehler, und wie lautet das richtige Ergebnis mit dem größten gemeinsamen Faktor?',
      'Fehler in Zeile □, richtig: 18x² − 12x = 6x(□x − □)', [1, 3, 2], ['1', '18 : 6', '12 : 6'],
      [(1, 2, '2', 'Zeile 2 genannt, die nur aus dem Fehler in Zeile 1 folgt'),
       (1, 3, '3', 'erst Zeile 3 genannt, die nur aus dem Fehler in Zeile 1 folgt'),
       (2, 6, '18 : 3', 'die Klammer von Bens Ergebnis 3x(6x − 4) übernommen'),
       (2, 9, '18 : 2', 'durch 2 statt durch 6 geteilt'),
       (3, 4, '12 : 3', 'die Klammer von Bens Ergebnis 3x(6x − 4) übernommen'),
       (3, 6, '12 : 2', 'durch 2 statt durch 6 geteilt')],
      'Zeile 1 ist falsch: Der größte gemeinsame Teiler von 18 und 12 ist 6; 3 ist nur ein gemeinsamer Teiler. Die Zeilen 2 und 3 rechnen mit 3x richtig weiter, aber in der Klammer von 3x(6x − 4) steckt noch der Faktor 2. Mit 6x: 18x² : 6x = 3x und 12x : 6x = 2, also 18x² − 12x = 6x(3x − 2). Probe: 6x · (−2) = −12x.',
      'Fehler-Detektiv, bei dem der Fehler schon im ersten Schritt liegt (nicht der größte Faktor); die Übungen lassen das Ergebnis nur eingeben.')
    A(lz, 'korrektur', 'darstellung', None, 2, LP,
      'Der Term 6x² + 15x wird auf drei Arten ausgeklammert: (1) 3(2x² + 5x), (2) 3x(2x + 5), (3) x(6x + 15). Welche Aussage stimmt?',
      ['Alle drei Produkte sind gleichwertig zu 6x² + 15x, denn jedes ergibt ausmultipliziert 6x² + 15x; nur (2) hat den größten Faktor.',
       'Nur (2) ist gleichwertig zu 6x² + 15x, denn die beiden anderen Produkte sind unvollständig ausgeklammert.',
       'Nur (1) und (3) sind gleichwertig, denn bei (2) steht vor der Klammer ein x zu viel.',
       'Keines der drei ist gleichwertig, denn beim Ausklammern verändert sich der Term.'], 0,
      {1: 'Auch (1) und (3) ergeben ausmultipliziert 6x² + 15x; sie sind nur nicht vollständig ausgeklammert.',
       2: '3x · 2x = 6x² und 3x · 5 = 15x; bei (2) steht der Faktor 3x zu Recht vor der Klammer.',
       3: 'Ausklammern verändert den Wert des Terms nicht; ausmultipliziert ergibt jedes Produkt wieder 6x² + 15x.'},
      '(1) 3 · 2x² = 6x², 3 · 5x = 15x. (2) 3x · 2x = 6x², 3x · 5 = 15x. (3) x · 6x = 6x², x · 15 = 15x. Alle drei sind gleichwertig. Nur (2) hat den größten gemeinsamen Faktor 3x ausgeklammert.',
      'Gleichwertig und vollständig ausgeklammert werden unterschieden; die Übungen prüfen nur auf Gleichwertigkeit.')
    A(lz, 'sicherung', 'begruenden', None, 2, LP,
      'Welche Aussage über den Term 6x² + 4x + 5 ist richtig?',
      ['Man kann nichts außer 1 ausklammern, denn die drei Glieder haben keinen gemeinsamen ganzzahligen Faktor über 1 und keinen gemeinsamen Faktor x.',
       'Man kann 2x ausklammern: 2x(3x + 2 + 5), denn 2x steckt in den ersten beiden Gliedern und die 5 bleibt.',
       'Man kann 2 ausklammern: 2(3x² + 2x + 5), denn die 2 steckt in 6 und in 4.',
       'Man kann x ausklammern: x(6x + 4 + 5), denn x steckt in jedem Glied der Summe, auch wenn man es nicht sieht.'], 0,
      {1: 'Ausmultipliziert ergibt 2x(3x + 2 + 5) = 6x² + 4x + 10x; es stimmt nicht.',
       2: 'Ausmultipliziert ergibt 2(3x² + 2x + 5) = 6x² + 4x + 10; die 5 wurde nicht mit 2 multipliziert.',
       3: 'Ausmultipliziert ergibt x(6x + 4 + 5) = 6x² + 4x + 5x; die 5 enthält kein x.'},
      'Ein Faktor darf nur ausgeklammert werden, wenn er in jedem Glied steckt. Die 5 hat mit 6 und 4 keinen gemeinsamen Teiler außer 1 und enthält kein x. Die Proben ergeben: 2x · 5 = 10x, 2 · 5 = 10 und x · 5 = 5x, nie die 5.',
      'Begründung, warum nicht ausgeklammert werden kann; die Übungen haben immer einen gemeinsamen Faktor.')
    Z(lz, 'sicherung', 'parameter', None, 3, LP,
      'Der Term 18x² + kx hat den größten gemeinsamen Faktor 6x, und k ist eine ganze Zahl zwischen 7 und 20. Wie groß ist k?',
      12, '12',
      [(6, '6', 'k gleich der 6 aus 6x gesetzt; 6 liegt aber nicht zwischen 7 und 20'),
       (18, '18', 'k = 18 gewählt; dann wäre der größte gemeinsame Faktor sogar 18x'),
       (9, '18 : 2', 'die Hälfte von 18 genommen, dann wäre der gemeinsame Faktor nur 9x'),
       (3, '18 : 6', 'den Faktor 18 : 6 = 3 für k genommen')],
      'k muss ein Vielfaches von 6 sein, damit 6 in k steckt: 12 oder 18 (zwischen 7 und 20). Bei k = 18 wäre der größte gemeinsame Faktor 18x, nicht 6x. Bei k = 12 ist der größte gemeinsame Teiler von 18 und 12 gleich 6. Also ist k = 12.',
      'k muss so gewählt werden, dass der Faktor genau 6x und nicht größer ist; die Übungen suchen den Faktor zu gegebenen Gliedern.')
    L(lz, 'sicherung', 'transfer', 'anwenden', 2, LP,
      'Ein Beet ist (5x + 3) m lang. Seine Fläche beträgt 20x² + 12x Quadratmeter. Wie breit ist das Beet? Trage die Breite als Term ein.',
      'Breite = □x m', [4], ['20 : 5'],
      [(1, 3, '3', 'die Zahl 3 der Länge als Breite genommen'),
       (1, 12, '12 : 1', 'den Faktor vor x im zweiten Glied (12) als Breite genommen'),
       (1, 15, '20 − 5', 'die Zahlen vor x subtrahiert statt dividiert')],
      'Fläche = Länge · Breite, also 20x² + 12x = (5x + 3) · Breite. Man klammert 4x aus: 20x² + 12x = 4x · (5x + 3). Die Breite ist 4x m.',
      'Die Breite wird aus Fläche und Länge durch Ausklammern erschlossen; die Übungen geben die Breite vor.')
    # ---------------- binomisch ----------------
    lz = 'binomisch'
    L(lz, 'test', 'fehler', 'fehler_detektiv', 3, LP,
      'Tim berechnet (2x − 5)². Zeile 1: (2x − 5)² bedeutet (2x − 5) · (2x − 5). Zeile 2: Man darf jedes Glied einzeln quadrieren: (2x − 5)² = (2x)² − 5². Zeile 3: Also ist (2x − 5)² = 4x² − 25. In welcher Zeile steckt der erste Fehler, und wie lautet das richtige Ergebnis?',
      'Fehler in Zeile □, richtig: (2x − 5)² = □x² − □x + □', [2, 4, 20, 25], ['2', '2 · 2', '2 · 2 · 5', '5 · 5'],
      [(3, 10, '2 · 5', 'beim Mittelglied den Faktor 2 aus 2x vergessen: 2 · 5 = 10'),
       (3, 0, '0', 'das Mittelglied weggelassen, wie Tim in Zeile 2'),
       (3, 40, '2 · 2 · 2 · 5', 'beim Mittelglied zweimal die 2 aus 2x genommen'),
       (4, 5, '5', 'die 5 nicht quadriert'),
       (1, 1, '1', 'Zeile 1 für falsch gehalten, obwohl (2x − 5)² wirklich (2x − 5) · (2x − 5) bedeutet'),
       (1, 3, '3', 'erst Zeile 3 genannt, die nur aus dem Fehler in Zeile 2 folgt'),
       (2, 2, '2', '(2x)² als 2x² gerechnet, die 2 nicht quadriert')],
      'Zeile 1 stimmt. In Zeile 2 fehlt das Mittelglied: (a − b)² = a² − 2ab + b². Mit a = 2x, b = 5: (2x)² − 2 · 2x · 5 + 5² = 4x² − 20x + 25. Probe mit x = 1: (2 − 5)² = 9 und 4 − 20 + 25 = 9; Tims 4 − 25 = −21 passt nicht.',
      'Die Übungen multiplizieren die Klammer aus; hier muss der klassische Fehler „(a − b)² = a² − b²“ gefunden und das ganze Ergebnis berichtigt werden.')
    Z(lz, 'korrektur', 'parameter', None, 2, LP,
      'Für welche positive Zahl k ist der Term 25x² − kx + 4 das Quadrat einer Differenz (a − b)²?',
      20, '2 · 5 · 2',
      [(10, '5 · 2', 'das doppelte Produkt ohne den Faktor 2 gerechnet'),
       (7, '5 + 2', 'die beiden Zahlen 5 und 2 addiert'),
       (29, '25 + 4', 'die beiden Quadratzahlen addiert')],
      '25x² = (5x)² und 4 = 2². Das Quadrat ist (5x − 2)² = 25x² − 2 · 5x · 2 + 4 = 25x² − 20x + 4. Also ist k = 20.',
      'Der Parameter liegt im Mittelglied einer Differenz; die Übungen ergänzen nur ein Glied bei kleinen Zahlen.')
    A(lz, 'korrektur', 'begruenden', None, 2, LP,
      'Warum gilt (a + b)² = a² + b² nicht? Welche Antwort stimmt?',
      ['Für a = 3, b = 4 ist (3 + 4)² = 49 und 3² + 4² = 25: Das doppelte Produkt 2ab fehlt und ist nur bei a = 0 oder b = 0 gleich 0.',
       'Für a = 3 und b = 4 ist (3 + 4)² = 25 und 3² + 4² = 25; die Formel stimmt für alle Zahlen.',
       'Die Formel stimmt nur, wenn b eine negative Zahl ist, denn dann ist das mittlere Glied gleich null.',
       'Für a = 3 und b = 4 ist (3 + 4)² = 14 und 3² + 4² = 25; das Quadrat der Summe ist immer kleiner.'], 0,
      {1: '(3 + 4)² = 7² = 49 und nicht 25.',
       2: 'Erfindet eine Einschränkung; die Formel stimmt nur, wenn a oder b gleich 0 ist (dann ist 2ab = 0).',
       3: '(3 + 4)² = 7² = 49, nicht 14 (14 ist 2 · 7); und die Summe zum Quadrat ist hier größer.'},
      '(3 + 4)² = 7² = 49. 3² + 4² = 9 + 16 = 25. Der Unterschied 24 ist 2 · 3 · 4 = 2ab. Allgemein: (a + b)² = a² + 2ab + b².',
      'Gegenbeispiel mit Zahlen als Begründung; die Übungen lassen nur ausmultiplizieren.')
    L(lz, 'korrektur', 'darstellung', None, 2, LP,
      'Ein Quadrat hat die Seitenlänge (x + 5) cm. Um wie viel cm² ist seine Fläche größer als die eines Quadrats mit der Seitenlänge x cm?',
      'Zuwachs: □x + □ cm²', [10, 25], ['2 · 5', '5 · 5'],
      [(1, 5, '5', 'beim Zuwachs nur die Zahl 5 statt 2 · 5 genommen'),
       (1, 25, '5 · 5', 'den x-Anteil mit 25 verwechselt'),
       (2, 5, '5', 'die 5 nicht quadriert'),
       (2, 10, '2 · 5', 'das Mittelglied als Zahlenglied genommen')],
      '(x + 5)² = x² + 10x + 25. Davon geht das kleine Quadrat x² ab: Zuwachs = 10x + 25. Das sind zwei Rechtecke 5 · x und ein kleines Quadrat 5 · 5.',
      'Darstellungswechsel Figur → Term mit Vergleich zweier Quadrate; die Übungen quadrieren nur.')
    A(lz, 'sicherung', 'begruenden', None, 2, LP,
      'Mia behauptet: „(x − 3)² ist für jede Zahl x größer als 0.“ Welche Aussage stimmt?',
      ['Nein: Für x = 3 ist (x − 3)² = 0, denn die Klammer ist dann 0; sonst ist der Wert positiv.',
       'Nein: Für x kleiner als 3 ist (x − 3)² negativ, zum Beispiel (1 − 3)² = −4, denn die Klammer ist dann negativ.',
       'Ja: Ein Quadrat ist immer größer als 0, denn Minus mal Minus ergibt Plus.',
       'Nein: Der Wert ist nur für x größer als 3 positiv, denn nur dann ist die Klammer selbst positiv.'], 0,
      {1: 'Die negative Klammer wird quadriert; Minus mal Minus ergibt Plus, der Wert ist positiv, zum Beispiel (0 − 3)² = 9.',
       2: 'Für x = 3 ist die Klammer 0, und 0² ist 0, nicht größer als 0.',
       3: 'Auch für x kleiner als 3 ist der Wert positiv, zum Beispiel (1 − 3)² = 4.'},
      'Ein Quadrat ist nie negativ. (x − 3)² = x² − 6x + 9. Für x = 3 ist der Wert genau 0: (3 − 3)² = 0. Für jede andere Zahl ist er positiv, zum Beispiel (0 − 3)² = 9 und (5 − 3)² = 4.',
      'Eine Aussage über alle Zahlen wird mit einem Gegenfall (x = 3) geprüft; die Übungen berechnen Werte.')
    L(lz, 'sicherung', 'transfer', None, 2, LP,
      'Für x = 4 ist (x + 3)² = 49, aber x² + 9 = 25. Der Unterschied der Terme (x + 3)² und x² + 9 lässt sich selbst als Term mit x schreiben. Wie groß ist er für x = 4, und welche Zahl steht in diesem Term vor x?',
      'Unterschied bei x = 4: □; Zahl vor x: □', [24, 6], ['49 − 25', '2 · 3'],
      [(1, 49, '7 · 7', 'nur den Wert von (x + 3)² angegeben'),
       (1, 25, '16 + 9', 'nur den Wert von x² + 9 angegeben'),
       (1, 6, '2 · 3', 'die Zahl vor x statt des Unterschieds eingetragen'),
       (2, 9, '3 · 3', 'die Zahl 9 aus x² + 9 genommen'),
       (2, 3, '3', 'nur die 3 aus der Klammer genommen')],
      '(x + 3)² = x² + 6x + 9. Das ist 6x mehr als x² + 9. Für x = 4 ist der Unterschied 6 · 4 = 24 (49 − 25 = 24). Vor x steht die Zahl 6; es ist das doppelte Produkt 2 · x · 3.',
      'Das gemischte Glied wird als Unterschied zwischen (x + 3)² und x² + 9 erkannt; die Übungen multiplizieren Klammern aus.')
    L(lz, 'sicherung', 'umkehr', None, 3, LP,
      'Ein Quadrat hat den Flächeninhalt 9x² + 12x + 4 (in cm²), dabei ist x eine positive Zahl. Wie groß ist sein Umfang? Gib ihn als Term an.',
      'Umfang = □x + □ cm', [12, 8], ['4 · 3', '4 · 2'],
      [(1, 6, '3 + 3', 'nur zwei Seiten statt vier gerechnet (Umfang von 2 Seiten)'),
       (1, 9, '9', 'den Faktor 9 der Fläche als Faktor des Umfangs genommen'),
       (2, 4, '4', 'die Zahl 4 der Fläche als Zahl im Umfang genommen'),
       (2, 2, '2', 'nur die Seitenzahl 2 genommen, nicht mal 4')],
      '9x² + 12x + 4 = (3x + 2)², denn (3x)² = 9x², 2 · 3x · 2 = 12x und 2² = 4. Die Seite ist (3x + 2) cm lang. Der Umfang ist 4 · (3x + 2) = 12x + 8 cm.',
      'Aus der Fläche wird mit der binomischen Formel auf die Seite geschlossen; die Übungen berechnen die Fläche aus der Seite.')
